fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, -20);
        host::display::state_set(2, -180);
        host::display::state_set(3, -340);
        host::display::state_set(4, 1);
        host::display::state_set(5, 2);
        host::display::state_set(6, 3);
        host::display::state_set(7, 0);
        host::display::state_set(10, t);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(8) == 0;
    host::display::state_set(8, down);
    if host::display::state_get(7) == 1 {
        host::display::clear(0x100010);
        host::display::draw_string(160, 180, "CRUSHED", 0xff4040, 4);
        host::display::draw_string(120, 250, "SURVIVED", 0x808080, 2);
        host::display::draw_number(270, 250, host::display::state_get(11), 0xffffff, 2);
        host::display::draw_string(120, 285, "BEST", 0x808080, 2);
        host::display::draw_number(270, 285, host::display::state_get(9), 0x00ff88, 2);
        host::display::draw_string(140, 340, "TAP TO RETRY", 0x808080, 2);
        if tap { host::display::state_set(0, 0); }
    } else {
        let mut px: i32 = host::display::pointer_x() - 16;
        if px < 0 { px = 0; }
        if px > w - 32 { px = w - 32; }
        let py: i32 = h - 44;
        let sec: i32 = (t - host::display::state_get(10)) / 60;
        host::display::state_set(11, sec);
        host::display::clear(0x0a0a12);
        host::display::fill_rect(px, py, 32, 32, 0x00ddff);
        let mut i: i32 = 0;
        while i < 3 {
            let mut ry: i32 = host::display::state_get(1 + i);
            let rnd: i32 = host::display::state_get(4 + i);
            let rx: i32 = hash(rnd * 100 + i) % (w - 32);
            let spd: i32 = 3 + hash(rnd * 7 + i) % 4;
            ry = ry + spd;
            if ry > h {
                host::display::state_set(4 + i, rnd + 1);
                ry = -30 - hash(rnd * 13 + i) % 120;
            }
            host::display::state_set(1 + i, ry);
            if rx + 32 > px && rx < px + 32 && ry + 32 > py && ry < py + 32 {
                host::display::state_set(7, 1);
                if sec > host::display::state_get(9) {
                    host::display::state_set(9, sec);
                }
            }
            host::display::fill_rect(rx, ry, 32, 32, 0x8a8a92);
            host::display::fill_rect(rx + 6, ry + 6, 8, 8, 0x5a5a62);
            i = i + 1;
        }
        host::display::draw_number(8, 6, sec, 0xffffff, 3);
    }
    host::display::present();
}
